from datetime import datetime
from rest_framework_jwt.settings import api_settings
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import DepartmentAuditAssignment

class GenerateAuditorInspectionTokenView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        department_code = request.data.get('department_code')
        if not department_code:
            return Response({'error': 'department_code required'}, status=status.HTTP_400_BAD_REQUEST)

        # Verify caller has an authorized active audit assignment for the department
        is_authorized = DepartmentAuditAssignment.objects.filter(
            auditor=request.user,
            department__code=department_code,
            is_active=True
        ).exists()
        if not is_authorized:
            return Response({'error': 'Not authorized to audit this department'}, status=status.HTTP_403_FORBIDDEN)

        payload = {
            'sub': request.user.id,
            'is_audit_token': True,
            'audited_department': department_code,
            'exp': datetime.utcnow() + api_settings.JWT_EXPIRATION_DELTA
        }
        jwt_encode_handler = api_settings.JWT_ENCODE_HANDLER
        token = jwt_encode_handler(payload)
        return Response({'audit_token': token, 'department_code': department_code})
